// Fase 0.3 (plano de cleanup): ícone compacto do logo pro PICKER (botões "Ícone/Completo/
// Nome"), pra trocar o rótulo de texto pelo desenho real do logo. currentColor não é
// setado aqui de propósito — os paths já carregam fill="currentColor" (ver comentário
// acima), então o SVG herda a cor de texto do próprio botão (ex.: --muted no estado
// "Nenhum"), sem precisar re-render ao trocar de estado (hover/on) — é só CSS.
// Cada logo tem uma proporção bem diferente (ícone é quase quadrado, full/nome são
// bem largos) — escala por altura E limita a largura, pra caber no botão sem distorcer.
export function logoPickSvg(kind, maxH = 15, maxW = 26) {
  const L = LOGOS[kind];
  if (!L) return '';
  const scale = Math.min(maxH / L.h, maxW / L.w);
  const w = Math.round(L.w * scale), h = Math.round(L.h * scale);
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${L.w} ${L.h}" aria-hidden="true">${L.inner}</svg>`;
}
